import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { inverseLerp } from "./src/math/inverseLerp.js";
import { lerp } from "./src/math/lerp.js";
{
{
{
const cases = [
            [0, 100, 0.5],
            [10, 20, 0.25],
            [-5, 5, 0.9],
            [100, 0, 0.3],
            [0.1, 0.3, 0.7],
        ];
        for (const [start, stop, fraction] of cases) {
            expect(inverseLerp(start, stop, lerp(start, stop, fraction))).toBeCloseTo(fraction);
            expect(lerp(start, stop, inverseLerp(start, stop, lerp(start, stop, fraction)))).toBeCloseTo(lerp(start, stop, fraction));
        }
}
}
}

